PRAGMA foreign_keys = ON;

UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"tall jackal-headed adult deity with strict upright ceremonial profile","appearance":{"face":["black jackal head with alert ears and calm forward gaze"],"body":["lean athletic adult humanoid body"]},"costumeLanguage":["black-and-gold funerary ceremonial regalia with broad collar and kilt"],"paletteCues":["black gold"],"temperament":["solemn","protective","judicial"],"mythologicalFacts":["god associated with embalming and protection of the dead"],"originalDesignChoices":["Keep the jackal head anatomically elegant and divine, not a furry anthropomorphic cartoon."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Anubis as an original MythCanvas interpretation. Preserve black jackal head, ankh, balance motif; keep tall jackal-headed adult deity with strict upright ceremonial profile. Use black-and-gold funerary ceremonial regalia with broad collar and kilt. Maintain a solemn presence."}') WHERE id = 'character-anubis';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"upright falcon-headed solar king crowned by a large clean sun disk","appearance":{"face":["falcon head with sharp composed gaze beneath the sun disk"],"body":["tall idealized adult humanoid body"]},"costumeLanguage":["formal pharaonic-style divine kilt and broad collar with sun disk crown"],"paletteCues":["solar red"],"temperament":["radiant","sovereign","eternal"],"mythologicalFacts":["major solar deity"],"originalDesignChoices":["Keep the sun disk simple and monumental; avoid angelic wings unless scene-specific."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Ra as an original MythCanvas interpretation. Preserve falcon head, sun disk with cobra, solar barque; keep upright falcon-headed solar king crowned by a large clean sun disk. Use formal pharaonic-style divine kilt and broad collar with sun disk crown. Maintain a radiant presence."}') WHERE id = 'character-ra';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"mummiform underworld king standing frontally with crossed crook and flail","appearance":{"face":["serene mature royal face with green skin"],"body":["wrapped mummiform body with controlled royal proportions"]},"costumeLanguage":["white mummy wrapping and royal mantle with Atef crown"],"paletteCues":["Nile green"],"temperament":["serene","judicial","resurrected"],"mythologicalFacts":["god of the dead, resurrection and kingship"],"originalDesignChoices":["Avoid horror-mummy treatment; he is a resurrected king and judge."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Osiris as an original MythCanvas interpretation. Preserve Atef crown, crook and flail, green skin; keep mummiform underworld king standing frontally with crossed crook and flail. Use white mummy wrapping and royal mantle with Atef crown. Maintain a serene presence."}') WHERE id = 'character-osiris';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"stately adult goddess with symmetrical protective wing arc and throne-sign crown","appearance":{"face":["clearly adult regal face with compassionate focused gaze"],"body":["graceful adult proportions"]},"costumeLanguage":["fitted linen dress and broad collar with royal throne-sign crown"],"paletteCues":["royal blue"],"temperament":["protective","intelligent","regal"],"mythologicalFacts":["goddess associated with magic, motherhood and kingship"],"originalDesignChoices":["Wings should read as sacred iconography, not a generic angel design."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Isis as an original MythCanvas interpretation. Preserve throne-sign crown, protective wings, ankh; keep stately adult goddess with symmetrical protective wing arc and throne-sign crown. Use fitted linen dress and broad collar with royal throne-sign crown. Maintain a protective presence."}') WHERE id = 'character-isis';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"falcon-headed young-adult kingly deity with a strong vertical double-crown silhouette","appearance":{"face":["falcon head with clear Eye of Horus markings"],"body":["athletic adult humanoid body"]},"costumeLanguage":["royal divine kilt and broad collar with double crown of Upper and Lower Egypt"],"paletteCues":["sky blue"],"temperament":["vigilant","royal","victorious"],"mythologicalFacts":["sky and kingship deity"],"originalDesignChoices":["Avoid generic bird-man armor; preserve Egyptian frontal-regal geometry."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Horus as an original MythCanvas interpretation. Preserve falcon head, Eye of Horus, double crown; keep falcon-headed young-adult kingly deity with a strong vertical double-crown silhouette. Use royal divine kilt and broad collar with double crown of Upper and Lower Egypt. Maintain a vigilant presence."}') WHERE id = 'character-horus';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"tall Set-animal-headed deity with long ears/snout and angular desert-storm profile","appearance":{"face":["stylized Set-animal head with long squared ears and curved snout"],"body":["strong lean adult humanoid build"]},"costumeLanguage":["formal Egyptian kilt, broad collar and restrained desert-war regalia"],"paletteCues":["desert red"],"temperament":["volatile","proud","formidable"],"mythologicalFacts":["god associated with desert, storms and disorder"],"originalDesignChoices":["Do not turn the Set animal into a jackal or donkey; keep its deliberately ambiguous canonical form."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Set as an original MythCanvas interpretation. Preserve Set-animal head, was sceptre, desert storm; keep tall Set-animal-headed deity with long ears/snout and angular desert-storm profile. Use formal Egyptian kilt, broad collar and restrained desert-war regalia. Maintain a volatile presence."}') WHERE id = 'character-set';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"graceful cat-headed adult goddess with compact sistrum and elegant vertical stance","appearance":{"face":["sleek black or dark feline head with alert calm eyes"],"body":["graceful adult humanoid body"]},"costumeLanguage":["refined linen dress with broad collar, sistrum and perfume-vessel accessories"],"paletteCues":["faience teal"],"temperament":["warm","watchful","protective"],"mythologicalFacts":["goddess associated with protection, household, joy and cats"],"originalDesignChoices":["Avoid sexualized cat-girl tropes, ears-on-human-head hybrids, or cartoon feline styling."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Bastet as an original MythCanvas interpretation. Preserve cat head, sistrum, perfume jar; keep graceful cat-headed adult goddess with compact sistrum and elegant vertical stance. Use refined linen dress with broad collar, sistrum and perfume-vessel accessories. Maintain a warm presence."}') WHERE id = 'character-bastet';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"lean ibis-headed deity with long beak, writing palette and measured scribe silhouette","appearance":{"face":["white-and-black ibis head with calm scholarly gaze"],"body":["slender adult humanoid build"]},"costumeLanguage":["scribe-like linen kilt and ceremonial collar with subtle lunar crown"],"paletteCues":["moon silver"],"temperament":["scholarly","precise","measured"],"mythologicalFacts":["god associated with writing, wisdom and reckoning"],"originalDesignChoices":["Do not replace ibis head with generic bird helmet or plague-doctor imagery."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Thoth as an original MythCanvas interpretation. Preserve ibis head, writing palette, moon disk; keep lean ibis-headed deity with long beak, writing palette and measured scribe silhouette. Use scribe-like linen kilt and ceremonial collar with subtle lunar crown. Maintain a scholarly presence."}') WHERE id = 'character-thoth';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"clearly adult goddess with horn-and-sun crown and broad open ceremonial stance","appearance":{"face":["adult warm regal face with gentle direct gaze"],"body":["graceful strong adult proportions"]},"costumeLanguage":["elegant linen dress with broad collar, sistrum and mirror"],"paletteCues":["copper rose"],"temperament":["joyful","maternal","welcoming"],"mythologicalFacts":["goddess associated with music, love, motherhood and sky"],"originalDesignChoices":["Avoid making the horn crown demonic or overly fantasy-like."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Hathor as an original MythCanvas interpretation. Preserve cow horns with sun disk, sistrum, mirror; keep clearly adult goddess with horn-and-sun crown and broad open ceremonial stance. Use elegant linen dress with broad collar, sistrum and mirror. Maintain a joyful presence."}') WHERE id = 'character-hathor';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"powerful lioness-headed adult goddess with sun disk and controlled warrior stance","appearance":{"face":["lioness head with intense forward gaze"],"body":["athletic strong adult humanoid body"]},"costumeLanguage":["structured Egyptian warrior-ceremonial dress with broad collar and sun crown"],"paletteCues":["burnished red"],"temperament":["fierce","controlled","protective"],"mythologicalFacts":["lioness goddess associated with destructive solar power and healing"],"originalDesignChoices":["Keep ferocity regal and controlled; no gore or feral monster posture."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Sekhmet as an original MythCanvas interpretation. Preserve lioness head, sun disk, uraeus; keep powerful lioness-headed adult goddess with sun disk and controlled warrior stance. Use structured Egyptian warrior-ceremonial dress with broad collar and sun crown. Maintain a fierce presence."}') WHERE id = 'character-sekhmet';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"broad crocodile-headed adult deity with grounded river-guardian posture","appearance":{"face":["crocodile head with heavy jaw and calm predatory eyes"],"body":["powerful adult humanoid build"]},"costumeLanguage":["Egyptian kilt and broad collar with river and solar details kept restrained"],"paletteCues":["Nile blue"],"temperament":["powerful","protective","primal"],"mythologicalFacts":["crocodile deity associated with Nile power, fertility and protection"],"originalDesignChoices":["Do not use fantasy dragon anatomy or heavy gladiator armor."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Sobek as an original MythCanvas interpretation. Preserve crocodile head, ankh, Nile water; keep broad crocodile-headed adult deity with grounded river-guardian posture. Use Egyptian kilt and broad collar with river and solar details kept restrained. Maintain a powerful presence."}') WHERE id = 'character-sobek';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"slender adult goddess with single tall feather and calm symmetrical ceremonial posture","appearance":{"face":["clearly adult serene face with balanced frontal gaze"],"body":["graceful adult proportions"]},"costumeLanguage":["minimal elegant linen dress and broad collar centered on the single feather emblem"],"paletteCues":["feather white"],"temperament":["serene","truthful","balanced"],"mythologicalFacts":["personification/goddess of truth, justice and cosmic order"],"originalDesignChoices":["Keep symmetry refined and minimal; avoid angel wings or generic justice-goddess blindfolds."],"avoid":["Greek or Roman armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Ma''at as an original MythCanvas interpretation. Preserve single ostrich feather, balance, ankh; keep slender adult goddess with single tall feather and calm symmetrical ceremonial posture. Use minimal elegant linen dress and broad collar centered on the single feather emblem. Maintain a serene presence."}') WHERE id = 'character-maat';
